import{_ as r,c as t,o as a,ag as s}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"CISA Resources","description":"","frontmatter":{"title":"CISA Resources"},"headers":[],"relativePath":"cybersecurity/cisa-resources.md","filePath":"cybersecurity/cisa-resources.md","lastUpdated":null}'),i={name:"cybersecurity/cisa-resources.md"};function o(n,e,c,d,l,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="cisa-resources" tabindex="-1">CISA Resources <a class="header-anchor" href="#cisa-resources" aria-label="Permalink to &quot;CISA Resources&quot;">​</a></h1><h2 id="who-is-cisa" tabindex="-1">Who is CISA <a class="header-anchor" href="#who-is-cisa" aria-label="Permalink to &quot;Who is CISA&quot;">​</a></h2><p>The <strong>Cybersecurity and Infrastructure Security Agency (CISA)</strong> leads the national effort to understand, manage, and reduce risks to the cyber and physical infrastructure of the United States. It connects stakeholders in industry and government with resources, analyses, and tools to improve their cyber, communications, and physical security and resilience. This ensures a secure infrastructure for the American people. <a href="https://www.cisa.gov/about-cisa" target="_blank" rel="noreferrer">Source: CISA Overview</a></p><h3 id="cisa-free-cybersecurity-services-and-tools" tabindex="-1">CISA Free Cybersecurity Services and Tools <a class="header-anchor" href="#cisa-free-cybersecurity-services-and-tools" aria-label="Permalink to &quot;CISA Free Cybersecurity Services and Tools&quot;">​</a></h3><p>On September 24, 2022, CISA released a list of free cybersecurity tools and services:</p><blockquote><p>&quot;As part of our continuing mission to reduce cybersecurity risk across U.S. critical infrastructure partners and state, local, tribal, and territorial governments, CISA has compiled a list of free cybersecurity tools and services to help organizations further advance their security capabilities. This living repository includes cybersecurity services provided by CISA, widely used open-source tools, and free tools and services offered by private and public sector organizations across the cybersecurity community.&quot; <a href="https://www.cisa.gov/free-cybersecurity-services-and-tools" target="_blank" rel="noreferrer">Source: CISA Free Cybersecurity Services</a></p></blockquote><h3 id="general-cisa-cybersecurity-guidelines" tabindex="-1">General CISA Cybersecurity Guidelines <a class="header-anchor" href="#general-cisa-cybersecurity-guidelines" aria-label="Permalink to &quot;General CISA Cybersecurity Guidelines&quot;">​</a></h3><ol><li><p><strong>Fix</strong> known security flaws in software by referencing the <a href="https://www.cisa.gov/known-exploited-vulnerabilities-catalog" target="_blank" rel="noreferrer">CISA Known Exploited Vulnerabilities Catalog</a>. Regularly update software to the latest versions as per vendor instructions.</p></li><li><p><strong>Implement <a href="https://www.cisa.gov/mfa" target="_blank" rel="noreferrer">multifactor authentication (MFA)</a></strong>. MFA requires two or more authenticators to verify identity, providing enhanced protection over just a username and password.</p></li><li><p><strong>Halt <a href="https://www.cisa.gov/BadPractices" target="_blank" rel="noreferrer">bad practices</a></strong> such as using end-of-life software, systems with default passwords, and lacking MFA for critical systems.</p></li><li><p><strong>Sign up</strong> for CISA’s Cyber Hygiene Vulnerability Scanning by emailing <a href="mailto:vulnerability@cisa.dhs.gov" target="_blank" rel="noreferrer">vulnerability@cisa.dhs.gov</a>. Weekly reports help secure internet-facing systems.</p></li><li><p><strong>Get your Stuff Off Search (S.O.S.)</strong> by reducing internet-visible attack surfaces. Learn more at <a href="https://www.cisa.gov/publication/stuff-off-search" target="_blank" rel="noreferrer">Get Your Stuff Off Search (S.O.S.)</a>.</p></li></ol><h3 id="cisa-tool-recommendations" tabindex="-1">CISA Tool Recommendations <a class="header-anchor" href="#cisa-tool-recommendations" aria-label="Permalink to &quot;CISA Tool Recommendations&quot;">​</a></h3><h3 id="reducing-the-likelihood-of-a-cyber-incident" tabindex="-1">Reducing the Likelihood of a Cyber Incident <a class="header-anchor" href="#reducing-the-likelihood-of-a-cyber-incident" aria-label="Permalink to &quot;Reducing the Likelihood of a Cyber Incident&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Skill Level</th><th>Owner</th><th>Description</th><th>Link</th></tr></thead><tbody><tr><td>Network Reporting</td><td>Basic</td><td>ShadowServer</td><td>Reports on network state and security exposures</td><td><a href="https://www.shadowserver.org/what-we-do/network-reporting/" target="_blank" rel="noreferrer">ShadowServer</a></td></tr><tr><td>Vulcan Cyber Remedy Cloud</td><td>Basic</td><td>Vulcan Cyber</td><td>Searchable database of vulnerability remedies</td><td><a href="https://vulcan.io/remedy-cloud/" target="_blank" rel="noreferrer">Remedy Cloud</a></td></tr><tr><td>Ransomware Risk Assessment</td><td>Basic</td><td>Zscaler</td><td>Assesses ransomware-specific intrusion defenses</td><td><a href="https://testmydefenses.com/ransomware-assessment/" target="_blank" rel="noreferrer">Test My Defenses</a></td></tr><tr><td>Internet Threat Exposure</td><td>Basic</td><td>Zscaler</td><td>Evaluates cyber risk posture</td><td><a href="http://securitypreview.zscaler.com/" target="_blank" rel="noreferrer">Zscaler Scan</a></td></tr><tr><td>CISA Vulnerability Scanning</td><td>Basic</td><td>CISA</td><td>Scans public IPs for vulnerabilities</td><td><a href="mailto:vulnerability@cisa.dhs.gov" target="_blank" rel="noreferrer">vulnerability@cisa.dhs.gov</a></td></tr><tr><td>CISA Web Application Scanning</td><td>Basic</td><td>CISA</td><td>Evaluates web applications for security risks</td><td><a href="mailto:vulnerability@cisa.dhs.gov" target="_blank" rel="noreferrer">vulnerability@cisa.dhs.gov</a></td></tr><tr><td>Cloudflare DDoS Protection</td><td>Basic</td><td>Cloudflare</td><td>Protects against DDoS attacks</td><td><a href="https://www.cloudflare.com/plans/free/" target="_blank" rel="noreferrer">Cloudflare Free</a></td></tr><tr><td>Quad9</td><td>Basic</td><td>Open Source</td><td>Blocks malware and phishing sites</td><td><a href="https://quad9.net/" target="_blank" rel="noreferrer">Quad9</a></td></tr><tr><td>Wireshark</td><td>Advanced</td><td>Open Source</td><td>Network protocol analyzer</td><td><a href="https://www.wireshark.org/" target="_blank" rel="noreferrer">Wireshark</a></td></tr><tr><td>Snort</td><td>Advanced</td><td>Cisco</td><td>Intrusion detection and prevention</td><td><a href="https://www.snort.org/" target="_blank" rel="noreferrer">Snort</a></td></tr></tbody></table><h3 id="other-tools" tabindex="-1">Other Tools <a class="header-anchor" href="#other-tools" aria-label="Permalink to &quot;Other Tools&quot;">​</a></h3><ul><li><p><a href="https://docs.microsoft.com/en-us/windows/security/threat-protection/microsoft-defender-application-guard" target="_blank" rel="noreferrer">Microsoft Defender Application Guard</a>: Provides isolated browsing to protect against malware.</p></li><li><p><a href="https://docs.microsoft.com/en-us/windows/security/information-protection/bitlocker/bitlocker-how-to-deploy-on-windows-server" target="_blank" rel="noreferrer">BitLocker</a>: Encrypts Windows systems to secure data.</p></li><li><p><a href="https://www.aircrack-ng.org/" target="_blank" rel="noreferrer">Aircrack</a>: Tests wireless network security.</p></li></ul><h3 id="ensure-preparedness-for-intrusions" tabindex="-1">Ensure Preparedness for Intrusions <a class="header-anchor" href="#ensure-preparedness-for-intrusions" aria-label="Permalink to &quot;Ensure Preparedness for Intrusions&quot;">​</a></h3><h3 id="cyber-readiness" tabindex="-1">Cyber Readiness <a class="header-anchor" href="#cyber-readiness" aria-label="Permalink to &quot;Cyber Readiness&quot;">​</a></h3><ul><li><p><a href="https://www.projectspectrum.io/#/cyber-readiness-check" target="_blank" rel="noreferrer">Cyber Readiness Check (CRCs)</a>: Evaluates organizational security readiness.</p></li><li><p><a href="https://www.purple-knight.com/" target="_blank" rel="noreferrer">Purple Knight</a>: Scans Active Directory for vulnerabilities and risks.</p></li></ul><p><em>Categorty:Tech</em></p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3>',18)])])}const p=r(i,[["render",o]]);export{f as __pageData,p as default};
